/// <summary>
/// The <c>METBulkFreeTextInvoiceWorkflowSubmissionMainController</c> class for the batch job to approve / reject / delegate free text invoices.
/// </summary>
/// Added for CFR4 bulk approval AR invoice
public class METBulkFreeTextInvoiceWorkflowSubmissionMainController extends SysOperationServiceController implements BatchRetryable
{
}

Method.Source:
/// <summary>
/// Runs the class with the specified arguments.
/// </summary>
/// <param name="_args">The arguments passed to the subtask.</param>
public static void main(Args _args)
{
    METBulkFreeTextInvoiceWorkflowSubmissionMainController controller = METBulkFreeTextInvoiceWorkflowSubmissionMainController::construct();
    controller.parmArgs(_args);
    controller.parmLoadFromSysLastValue(false);
    controller.startOperation();
}

/// <summary>
/// Specifies if the batch task is retryable for transient exceptions.
/// </summary>
/// <returns>
/// <c>true</c> if the batch task is retryable; otherwise, <c>false</c>.
/// </returns>
[Hookable(false)]
final boolean isRetryable()
{
    return true;
}

/// <summary>
/// Constructs an instance of the <c>METBulkFreeTextInvoiceWorkflowSubmissionMainController</c> class.
/// </summary>
/// <param name="_executionMode">The execution mode for the operation, either synchronous or scheduled batch.</param>
/// <returns>An instance of the <c>METBulkFreeTextInvoiceWorkflowSubmissionMainController</c> class.</returns>
public static METBulkFreeTextInvoiceWorkflowSubmissionMainController construct(SysOperationExecutionMode _executionMode = SysOperationExecutionMode::Synchronous)
{
    METBulkFreeTextInvoiceWorkflowSubmissionMainController controller = new METBulkFreeTextInvoiceWorkflowSubmissionMainController();
    controller.parmExecutionMode(_executionMode);

    return controller;
}

/// <summary>
/// Initializes a new instance of the <c>METBulkFreeTextInvoiceWorkflowSubmissionMainController</c> class.
/// </summary>
protected void new()
{
    super(classStr(METBulkFreeTextInvoiceWorkflowSubmissionMainService),
            methodStr(METBulkFreeTextInvoiceWorkflowSubmissionMainService, execute),
            SysOperationExecutionMode::ScheduledBatch);
}

/// <summary>
/// Sets the caption of the batch job.
/// </summary>
/// <returns>The description of the class.</returns>
public ClassDescription defaultCaption()
{
    return "@MET:METFTIWFSubmissionCaption";
}
